const account = $input.item.json;
const key = "YOUR_UNIPILE_API_KEY";
const base = "https://YOUR_UNIPILE_DSN";
let items = [];
let cursor = null;
do {
  const url = base + '/api/v1/chats?account_id=' + account.accountId + '&limit=100' + (cursor ? '&cursor=' + cursor : '');
  const resp = await this.helpers.httpRequest({ method: 'GET', url, headers: { 'X-API-KEY': key }, json: true });
  items = items.concat(resp.items || []);
  cursor = resp.cursor || null;
} while (cursor);
const contactedIds = new Set(items.map(c => c.attendee_provider_id).filter(Boolean));
return [{ json: { ...account, contactedIds: Array.from(contactedIds) } }];

const account = $input.item.json;
const key = "YOUR_UNIPILE_API_KEY";
const base = "https://YOUR_UNIPILE_DSN";
const contactedIds = new Set(account.contactedIds);

// Early-exit : on arrete de paginer des qu'on trouve un candidat, au lieu de tout charger
// d'abord. Reduit fortement le temps d'execution de ce node (source principale des
// crashs out-of-memory observes sur cette instance n8n a ressources limitees).
let cursor = null;
let pick = null;
do {
  const url = base + '/api/v1/users/relations?account_id=' + account.accountId + '&limit=100' + (cursor ? '&cursor=' + cursor : '');
  const resp = await this.helpers.httpRequest({ method: 'GET', url, headers: { 'X-API-KEY': key }, json: true });
  const items = resp.items || [];
  pick = items.find(r => {
    const pid = r.member_id || r.provider_id;
    return pid && !contactedIds.has(pid);
  }) || null;
  if (pick) break;
  cursor = resp.cursor || null;
} while (cursor);

if (!pick) return [];
return [{ json: { ...account, providerId: pick.member_id || pick.provider_id, publicIdentifier: pick.public_identifier, prenom: pick.first_name, name: (pick.first_name || '') + ' ' + (pick.last_name || ''), headline: pick.headline || '' } }];

const contact = $input.item.json;
const key = "YOUR_UNIPILE_API_KEY";
const base = "https://YOUR_UNIPILE_DSN";

const profile = await this.helpers.httpRequest({
  method: 'GET',
  url: base + '/api/v1/users/' + encodeURIComponent(contact.publicIdentifier) + '?account_id=' + contact.accountId + '&linkedin_sections=experience',
  headers: { 'X-API-KEY': key },
  json: true
});

let posts = { items: [] };
for (let attempt = 0; attempt < 2; attempt++) {
  try {
    posts = await this.helpers.httpRequest({
      method: 'GET',
      url: base + '/api/v1/users/' + contact.providerId + '/posts?account_id=' + contact.accountId + '&limit=20',
      headers: { 'X-API-KEY': key },
      json: true
    });
    break;
  } catch (e) {
    if (attempt === 0) {
      await new Promise(r => setTimeout(r, 3000));
    }
  }
}

return [{ json: { ...contact, profile, posts } }];

const contact = $input.item.json;
const ghToken = 'YOUR_GITHUB_TOKEN';
const headers = { 'Authorization': 'token ' + ghToken, 'Accept': 'application/vnd.github.raw', 'User-Agent': 'n8n-icebreaker' };

const personaUrl = 'https://api.github.com/repos/Martenous2000/mon-setter-bot/contents/prompts/personas/' + contact.personaFile;
const reglesUrl = 'https://api.github.com/repos/Martenous2000/mon-setter-bot/contents/prompts/icebreakers-regles-strictes.md';

let personaMd = '';
let reglesMd = '';
try {
  personaMd = await this.helpers.httpRequest({ method: 'GET', url: personaUrl, headers, encoding: 'utf8' });
} catch (e) { personaMd = ''; }
try {
  reglesMd = await this.helpers.httpRequest({ method: 'GET', url: reglesUrl, headers, encoding: 'utf8' });
} catch (e) { reglesMd = ''; }

return [{ json: { ...contact, personaMd, reglesMd } }];

const combined = $input.item.json;
const lead = combined.profile;
const contact = combined;
const postsResp = combined.posts;
const personaMd = combined.personaMd || '';
const reglesMd = combined.reglesMd || '';

const prenom = contact.prenom || '';
const headline = contact.headline || '';
const work = (lead.work_experience && lead.work_experience[0]) || {};
const companyName = work.company || '';
const startDate = work.start || '';

function dureeExacte(start) {
  if (!start) return '';
  const parts = start.split('/');
  if (parts.length !== 3) return '';
  const [m, d, y] = parts.map(Number);
  const sd = new Date(y, m - 1, d);
  const now = new Date();
  let months = (now.getFullYear() - sd.getFullYear()) * 12 + (now.getMonth() - sd.getMonth());
  if (months < 12) return months + ' mois';
  const years = Math.floor(months / 12);
  return years + ' an' + (years > 1 ? 's' : '');
}
const dureeReelle = dureeExacte(startDate);
const isSelfEmployed = /^(self[- ]?employed|freelance|ind[ee]pendant|auto[- ]?entrepreneur)$/i.test((companyName || '').trim());

const posts = postsResp.items || [];
const parseDate = (v) => {
  if (!v) return 0;
  if (typeof v === 'string') {
    const m = v.match(/^(\d+)(m|h|d|w|mo|yr)$/);
    if (m) {
      const n = parseInt(m[1], 10);
      const unitMs = { m: 60000, h: 3600000, d: 86400000, w: 7 * 86400000, mo: 30 * 86400000, yr: 360 * 86400000 };
      return Date.now() - n * unitMs[m[2]];
    }
  }
  return new Date(v).getTime() || 0;
};
const ownPosts = posts.filter(p => {
  const text = (p.text || '').trim();
  const isRepost = p.is_repost === true;
  return text.length > 20 && !isRepost;
}).sort((a, b) => (parseDate(b.date) || 0) - (parseDate(a.date) || 0));
const recentPost = ownPosts[0] || null;
const hasPosts = !!recentPost;
const hasUsableBio = (companyName && dureeReelle) || headline.trim().length > 15;

if (!hasPosts && !hasUsableBio) {
  return [{ json: { ...contact, icebreaker: '', skip: true } }];
}

// Le persona (charge depuis GitHub) contient deja les regles d'icebreaker specifiques
// au compte (Type 1/2, ton, langue). On l'utilise comme base du system prompt et on
// n'ajoute que le fallback global si le persona ne precise rien sur l'icebreaker.
const basePrompt = personaMd + (reglesMd ? ('\n\n---\n\n' + reglesMd) : '');

const dureeContext = isSelfEmployed
  ? ('Statut freelance/independant, activite/bio : ' + (headline || '(vide)'))
  : (companyName && dureeReelle)
    ? ('Entreprise : ' + companyName + ', duree exacte : ' + dureeReelle)
    : ('Bio / headline uniquement : ' + (headline || '(vide)'));

let userContent;
if (hasPosts) {
  const postText = (recentPost.text || '').substring(0, 800);
  userContent = 'Tu dois generer l\'icebreaker (premier message) pour ce prospect precis, en respectant STRICTEMENT ton persona et les regles d\'icebreaker ci-dessus (Type 1 si applicable vu qu\'un post recent existe).\n\nPrenom du prospect : ' + (prenom || '(aucun)') + '\nHeadline LinkedIn : ' + (headline || '(vide)') + '\nDernier post LinkedIn du prospect (utilise-le pour le Type 1) :\n' + postText + '\n\nReponds UNIQUEMENT avec le message final complet, rien d\'autre. Jamais de tiret cadratin, demi-cadratin, ou tiret simple utilise comme ponctuation entre deux idees (virgule ou point a la place).';
} else {
  userContent = 'Tu dois generer l\'icebreaker (premier message) pour ce prospect precis, en respectant STRICTEMENT ton persona et les regles d\'icebreaker ci-dessus (Type 2 car aucun post recent exploitable).\n\nPrenom du prospect : ' + (prenom || '(aucun)') + '\n' + dureeContext + '\n\nReponds UNIQUEMENT avec le message final complet, rien d\'autre. Jamais de tiret cadratin, demi-cadratin, ou tiret simple utilise comme ponctuation entre deux idees (virgule ou point a la place).';
}

let aiOutput = '';
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: { 'Authorization': 'Bearer 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', 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'anthropic/claude-opus-4', messages: [{ role: 'system', content: basePrompt }, { role: 'user', content: userContent }], temperature: 0.6, max_tokens: 280 }),
    json: true
  });
  aiOutput = (resp.choices[0].message.content || '').trim();
  if ((aiOutput.startsWith('"') && aiOutput.endsWith('"')) || (aiOutput.startsWith("'") && aiOutput.endsWith("'"))) aiOutput = aiOutput.slice(1, -1);
  aiOutput = aiOutput.replace(/\s*[\u2014\u2013]\s*/g, ', ').replace(/([a-zA-Z0-9])\s+-\s+([a-zA-Z0-9])/g, '$1, $2');
} catch(e) { aiOutput = ''; }

const icebreaker = aiOutput || '';
const skip = !icebreaker;
return [{ json: { ...contact, icebreaker, hasPosts, skip } }];
